import type { Server } from 'node:http';
import { WebSocketServer, type WebSocket } from 'ws';
import { getChatById, getSession } from './store.js';

type WsEvent = { event: string; payload?: unknown };

const userSockets = new Map<string, Set<WebSocket>>();

function addSocket(userId: string, ws: WebSocket): void {
  let set = userSockets.get(userId);
  if (!set) {
    set = new Set();
    userSockets.set(userId, set);
  }
  set.add(ws);
}

function removeSocket(userId: string, ws: WebSocket): void {
  const set = userSockets.get(userId);
  if (!set) return;
  set.delete(ws);
  if (set.size === 0) userSockets.delete(userId);
}

export function isUserOnline(userId: string): boolean {
  const set = userSockets.get(userId);
  return !!set && set.size > 0;
}

export function emitToUser(userId: string, event: string, payload: unknown): void {
  const set = userSockets.get(userId);
  if (!set) return;
  const raw = JSON.stringify({ event, payload });
  for (const ws of set) {
    if (ws.readyState === ws.OPEN) ws.send(raw);
  }
}

export async function emitToChat(
  chatId: string,
  event: string,
  payload: unknown,
  exceptUserId?: string,
): Promise<void> {
  const chat = await getChatById(chatId);
  if (!chat) return;
  for (const memberId of chat.memberIds) {
    if (exceptUserId && memberId === exceptUserId) continue;
    emitToUser(memberId, event, payload);
  }
}

export function attachWebSocket(httpServer: Server): void {
  const wss = new WebSocketServer({ server: httpServer, path: '/ws' });

  wss.on('connection', (ws, req) => {
    void (async () => {
      const url = new URL(req.url ?? '', 'http://localhost');
      const token = url.searchParams.get('token');
      if (!token) {
        ws.close(4001, 'unauthorized');
        return;
      }
      const session = await getSession(token);
      if (!session) {
        ws.close(4001, 'unauthorized');
        return;
      }
      const userId = session.userId;
      addSocket(userId, ws);

      ws.on('message', (data) => {
        void (async () => {
          let msg: WsEvent;
          try {
            msg = JSON.parse(String(data)) as WsEvent;
          } catch {
            return;
          }
          if (!msg || typeof msg.event !== 'string') return;

          if (msg.event === 'ping') {
            ws.send(JSON.stringify({ event: 'pong', payload: {} }));
            return;
          }

          if (msg.event === 'typing') {
            const payload = msg.payload as { chatId?: string } | undefined;
            const chatId = payload?.chatId;
            if (!chatId || typeof chatId !== 'string') return;
            const chat = await getChatById(chatId);
            if (!chat || !chat.memberIds.includes(userId)) return;
            await emitToChat(chatId, 'typing', { chatId, userId }, userId);
          }
        })();
      });

      ws.on('close', () => {
        removeSocket(userId, ws);
      });
    })();
  });
}
